// Reuse the pipeline's normalize + dedupe logic (from lib.js / portals.js).
// Output one item per unique job in the common schema:
// { id, title, company, location, url, posted_at, source, description }
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const key = (j.url || `${j.company}|${j.title}|${j.location}`).toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: j });
}
return out;

// Weighted multi-factor scoring + confidence (port of score.js).
// Attach j.score = { total, confidence, breakdown } to each item.
return $input.all();

